class redireccionarActions extends sfActions
{
  public function executeIndex()
  {
    return $this->forward('redireccionar', 'list');
  }
  
    public function verificaPrilegio($currentForm)
  { 
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
	}
	 
  }
  
  public function verificaPrilegioCerrar($currentForm)
  { 
 	$usuarioLoguiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuarioLoguiado)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
	}
	 	  
  }
  
  public function executeList()
  {
  	
    $this->redireccions = RedireccionPeer::doSelect(new Criteria());
  }

  public function executeShow()
  {
    $this->redireccion = RedireccionPeer::retrieveByPk($this->getRequestParameter('redireccion_id'));
    $this->forward404Unless($this->redireccion);
  }

  public function executeCreate()
  {
    $this->redireccion = new Redireccion();

    $this->setTemplate('edit');
  }

  public function executeRedireccion()
  { 
  	$this->verificaPrilegio("redireccionar/redireccion");
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $c = new Criteria();
    $c->addJoin(RedireccionPeer::REDIRECCION_ID,RedireccionUsuarioPeer::REDIRECCION_ID);
    $c->add(RedireccionUsuarioPeer::USUARIO_ID,$usuariologuiado);
    $c->add(RedireccionUsuarioPeer::ROLUSUREDIRECCION_ID,1);
    $c->add(RedireccionPeer::ESTADOREDIRECCION_ID,2);
    $resp  = RedireccionUsuarioPeer::doSelectOne($c);
	if($resp != null){
	  $a = new Criteria();
      $a->add(RedireccionUsuarioPeer::REDIRECCION_ID,$resp->getRedireccionId());
      $a->add(RedireccionUsuarioPeer::ROLUSUREDIRECCION_ID,2);
      $this->result  = RedireccionUsuarioPeer::doSelectOne($a);	
	  $this->redireccion = RedireccionPeer::retrieveByPk($resp->getRedireccionId());	
	}else{ 
		$this->redireccion = new Redireccion();
		$this->result = null;
	}	    
    //$this->setTemplate('edit');        
  }
  
  public function executeEdit()
  {
    $this->redireccion = RedireccionPeer::retrieveByPk($this->getRequestParameter('redireccion_id'));
    $this->forward404Unless($this->redireccion);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('redireccion_id'))
    {
      $redireccion = new Redireccion();
    }
    else
    {
      $redireccion = RedireccionPeer::retrieveByPk($this->getRequestParameter('redireccion_id'));
      $this->forward404Unless($redireccion);
    }

   //$redireccion->setRedireccionId($this->getRequestParameter('redireccion_id'));
    $redireccion->setEstadoredireccionId($this->getRequestParameter('estadoredireccion_id'));
    $redireccion->setMotivo($this->getRequestParameter('motivo'));
    
    if (!$this->getRequestParameter('fecha_inicial'))
    {      
      $redireccion->setFechaInicial(date("Y-m-d G:i:s"));
    }else{
	  $redireccion->setFechaInicial($this->getRequestParameter('fecha_inicial'));	
	}
    
    if (!$this->getRequestParameter('fecha_final'))
    {      
      $redireccion->setFechaFinal(date("Y-m-d G:i:s"));
    }else{
	  $redireccion->setFechaFinal($this->getRequestParameter('fecha_final')); 	
	}

    $redireccion->save();
    if($redireccion->getEstadoredireccionId() == 2){
    	if(!$this->getRequestParameter('redireccion_id')){
           $this->setUsuarioRedireccion($this->getRequestParameter('idUser'),$redireccion->getRedireccionId());
        }
        $this->cambioEstado(3);
	}else{
	    $this->cambioEstado(1);	
	}    
    return $this->redirect($this->getRequest()->getScriptName().'/redireccionar/show?redireccion_id='.$redireccion->getRedireccionId());
  }
  
  public function setUsuarioRedireccion($usuario_id, $redireccion_id)
  {
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	/*****************************Usuario Que redirecciona*********************************************************/
	$redir_user = new RedireccionUsuario();
  	$redir_user->setRedireccionId($redireccion_id);
  	$redir_user->setRolusuredireccionId(1);
  	$redir_user->setUsuarioId($usuariologuiado);
  	$redir_user->save();
  	/*************************Usuario al que se redirecciona*******************************************************/
  	$redir_user1 = new RedireccionUsuario();
  	$redir_user1->setRedireccionId($redireccion_id);
  	$redir_user1->setRolusuredireccionId(2);
  	$redir_user1->setUsuarioId($usuario_id);
  	$redir_user1->save();
  	/****************************Cambio de Estado Usuario**********************************************************
  	$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
  	$usuario->setEstadousuarioId(3);
  	$usuario->save();
  	/*************************************************************************************************************/
  }
  
  public function cambioEstado($estadoId)
  {
    /****************************Cambio de Estado Usuario**********************************************************/
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
  	$usuario->setEstadousuarioId($estadoId);
  	$usuario->save();
  	/*************************************************************************************************************/	
  }
  public function executeDelete()
  {
    $redireccion = RedireccionPeer::retrieveByPk($this->getRequestParameter('redireccion_id'));

    $this->forward404Unless($redireccion);

    $redireccion->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/redireccionar/list');
  }
}
